//! Validation of g-xTB 2.0.1 against the 2.0.1 program (data in tests/reference_v2/, generated by
//! scripts/make_reference_v2.py and scripts/capture_density_v2.py).

use axtb_gxtb::v2::scf::{Energies, Setup};
use axtb_gxtb::{Conventions, ScfOptions};
use serde_json::Value;
use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/reference_v2")
}

fn json(path: &Path) -> Value {
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

/// All reference molecules (group/name), sorted.
fn molecules() -> Vec<PathBuf> {
    let mut v = Vec::new();
    for g in ["reference", "elements"] {
        for e in std::fs::read_dir(root().join(g)).unwrap() {
            let p = e.unwrap().path();
            if p.join("summary.json").exists() {
                v.push(p);
            }
        }
    }
    v.sort();
    v
}

fn molecule(dir: &Path, conv: Conventions) -> axtb::Molecule {
    let input = json(&dir.join("input.json"));
    let charge = input["charge"].as_f64().unwrap();
    let uhf = input["uhf"].as_u64().unwrap() as usize;
    let xyz = std::fs::read_to_string(dir.join("mol.xyz")).unwrap();
    axtb_gxtb::v2::read_xyz(&xyz, charge, Some(uhf), conv).unwrap()
}

/// The program's total energy with 12 decimals (the ":: total energy" line of its printout).
fn program_total(dir: &Path) -> f64 {
    let out = std::fs::read_to_string(dir.join("xtb.out")).unwrap();
    let line = out.lines().find(|l| l.contains(":: total energy")).expect("total energy line");
    line.split_whitespace().nth(3).unwrap().parse().unwrap()
}

fn name(dir: &Path) -> String {
    dir.file_name().unwrap().to_string_lossy().into_owned()
}

/// (program term name, our value).
fn terms(e: &Energies) -> Vec<(&'static str, f64)> {
    vec![
        ("increment", e.increments),
        ("dispersion_nonsc", e.dispersion_three_body),
        ("first_order", e.first_order),
        ("second_order", e.second_order),
        ("third_order", e.third_order),
        ("fourth_order", e.fourth_order),
        ("aes", e.aes),
        ("exchange", e.exchange),
        ("spin", e.spin),
        ("dispersion_sc", e.dispersion),
        ("repulsion", e.repulsion),
    ]
}

/// The program's density of the last SCF iteration (spin channels as stored).
fn program_density(dir: &Path) -> Option<(Vec<Vec<f64>>, Value)> {
    let f = dir.join("density.json");
    if !f.exists() {
        return None;
    }
    let d = json(&f);
    let n = d["nao"].as_u64().unwrap() as usize;
    let mut p = Vec::new();
    for packed in d["density_packed"].as_array().unwrap() {
        let v: Vec<f64> = packed.as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
        let mut m = vec![0.0; n * n];
        let mut k = 0;
        for i in 0..n {
            for j in 0..=i {
                m[i * n + j] = v[k];
                m[j * n + i] = v[k];
                k += 1;
            }
        }
        p.push(m);
    }
    Some((p, d))
}

/// Every term at the program's density against the program's per-term energies.
#[test]
fn terms_at_program_density() {
    let mut worst: f64 = 0.0;
    for dir in molecules() {
        let Some((p, d)) = program_density(&dir) else { continue };
        let mol = molecule(&dir, Conventions::Gxtb);
        let setup = Setup::new(&mol, axtb_gxtb::v2::Model::v2_0_1(Conventions::Gxtb)).unwrap();
        assert_eq!(setup.nao, d["nao"].as_u64().unwrap() as usize, "{}", name(&dir));
        let st = setup.state(&p);
        let (e, _) = setup.evaluate(&st, false);
        let refq: Vec<f64> = d["shell_charges"].as_array().unwrap().iter().map(|x| x.as_f64().unwrap()).collect();
        let nsh = st.q.len();
        let dq = st.q.iter().zip(&refq[..nsh]).map(|(a, b)| (a - b).abs()).fold(0.0, f64::max);
        assert!(dq < 1e-13, "{}: shell charges {dq:e}", name(&dir));
        let mut line = format!("{:22} nsp {} dq {:8.1e}", name(&dir), p.len(), dq);
        for (k, v) in terms(&e) {
            let r = d["terms"][k].as_f64().unwrap_or(0.0);
            line += &format!(" {k} {:8.1e}", v - r);
            // the increments are sums of 1e3 Eh numbers: compare relative
            let tol = if k == "increment" { 1e-15 * r.abs() } else { 1e-13 };
            assert!((v - r).abs() <= tol, "{}: {k} {v} vs {r}", name(&dir));
            if k != "increment" {
                worst = worst.max((v - r).abs());
            }
        }
        // printed energies: electronic 14 significant digits, total 12 decimals
        let summ = json(&dir.join("summary.json"));
        let ee = summ["electronic_energy"].as_f64().unwrap();
        let de = e.electronic - ee;
        let dt = e.total - program_total(&dir);
        line += &format!(" | electronic {de:8.1e} total {dt:8.1e}");
        println!("{line}");
        assert!(de.abs() < 1e-13 * ee.abs().max(1.0) + 1e-13, "{}: electronic {de:e}", name(&dir));
        assert!(dt.abs() < 2e-12, "{}: total {dt:e}", name(&dir));
    }
    println!("worst term {worst:e}");
}

/// Program-mode SCF on every reference molecule: total energy, per-term energies and SCF
/// iterations against the program.
#[test]
fn scf_matches_program() {
    let opts = ScfOptions { conventions: Conventions::Gxtb, ..Default::default() };
    let (mut worst_e, mut worst_t) = (0.0f64, 0.0f64);
    let mut bad_iter = Vec::new();
    for dir in molecules() {
        let summ = json(&dir.join("summary.json"));
        let mol = molecule(&dir, Conventions::Gxtb);
        let setup = Setup::new(&mol, axtb_gxtb::v2::Model::v2_0_1(Conventions::Gxtb)).unwrap();
        let t = std::time::Instant::now();
        let r = match setup.scf(&opts) {
            Ok(r) => r,
            Err(e) => {
                println!("{:22} FAILED {e}", name(&dir));
                bad_iter.push(name(&dir));
                continue;
            }
        };
        let de = r.energies.total - program_total(&dir);
        let it = summ["scf_iterations"].as_u64().unwrap() as usize;
        let mut dterm: f64 = 0.0;
        for (k, v) in terms(&r.energies) {
            if k == "increment" {
                continue;
            }
            let rv = summ["terms"][k].as_f64().unwrap_or(0.0);
            dterm = dterm.max((v - rv).abs());
        }
        // printed SCF cycle energies (11 decimals)
        let cyc = summ["scf_cycles"].as_array().unwrap();
        let mut dcyc: f64 = 0.0;
        for (k, (e, _)) in r.history.iter().enumerate().take(cyc.len()) {
            dcyc = dcyc.max((e - cyc[k][1].as_f64().unwrap()).abs());
        }
        println!(
            "{:22} dE {:9.1e} terms {:8.1e} cycles {:8.1e} iter {:3} / {:3}  {:.3}s",
            name(&dir),
            de,
            dterm,
            dcyc,
            r.iterations,
            it,
            t.elapsed().as_secs_f64()
        );
        worst_e = worst_e.max(de.abs());
        worst_t = worst_t.max(dterm);
        if !["methane", "ammonium", "hydroxide", "TbCl3"].contains(&name(&dir).as_str()) {
            assert!(dterm < 1e-11, "{}: per-term energies {dterm:e}", name(&dir));
        }
        if r.iterations != it {
            bad_iter.push(name(&dir));
        }
    }
    println!("worst total {worst_e:e}, terms {worst_t:e}, iteration mismatches {bad_iter:?}");
    assert!(bad_iter.is_empty(), "iteration counts differ: {bad_iter:?}");
    assert!(worst_e < 1e-11, "total energy {worst_e:e}");
    // methane, ammonium, hydroxide (and the open f shell of TbCl3): the program fills one
    // orbital of a (near-)degenerate HOMO set fractionally (its electron count is not an
    // integer); which one depends on the eigensolver at round-off level, and the unconverged part
    // of the final density follows. Their per-term energies differ by up to 2.6e-11 Eh (TbCl3;
    // methane 9.1e-12, hydroxide 4.8e-12), their totals by < 1e-12 Eh, and they have moved by up
    // to 6e-10 Eh with earlier changes of round-off. Everything else agrees to 1e-11 per term,
    // nearly all to 1e-12; above that are SCFs whose terms (not totals) move with the summation
    // order of the density and H matrices: the heavy s-block hydrides (RbH 6.6e-12, FrH 9.5e-13;
    // FrH's terms also move by 3e-12 Eh under a rotation or a reversed atom order).
    assert!(worst_t < 1e-9, "terms {worst_t:e}");
}

/// Default conventions (CODATA 2022 units, integer electron count, smooth cutoffs) against
/// the program: same SCF, energies within a few 1e-11 Eh for these small molecules.
#[test]
fn default_conventions_near_program() {
    let opts = ScfOptions { conventions: Conventions::Axtb, ..Default::default() };
    let mut worst: f64 = 0.0;
    for dir in molecules() {
        let mol = molecule(&dir, Conventions::Axtb);
        let r = Setup::new(&mol, axtb_gxtb::v2::Model::v2_0_1(Conventions::Axtb)).unwrap().scf(&opts).unwrap();
        let summ = json(&dir.join("summary.json"));
        let de = r.energies.total - program_total(&dir);
        println!(
            "{:22} dE {:9.2e} iter {:3} / {:3}",
            name(&dir),
            de,
            r.iterations,
            summ["scf_iterations"].as_u64().unwrap()
        );
        worst = worst.max(de.abs());
    }
    println!("worst {worst:e}");
    assert!(worst < 1e-8, "{worst:e}");
}

/// Molecules larger than the program's cutoffs (C50H102, 148 bohr long; (H2O)100): program mode
/// reproduces the hard cutoffs (CN and repulsion 25 bohr, revD4 50/25 bohr, integral pairs);
/// the default conventions differ by the smooth switches (mainly the three-body tail beyond
/// 25 bohr).
#[test]
fn large_systems_match_program() {
    for name in ["c50h102", "water100"] {
        let dir = root().join("large").join(name);
        let summ = json(&dir.join("summary.json"));
        let mol = molecule(&dir, Conventions::Gxtb);
        let setup = Setup::new(&mol, axtb_gxtb::v2::Model::v2_0_1(Conventions::Gxtb)).unwrap();
        let r = setup.scf(&ScfOptions { conventions: Conventions::Gxtb, ..Default::default() }).unwrap();
        let ep = program_total(&dir);
        let de = r.energies.total - ep;
        let mut dterm: f64 = 0.0;
        for (k, v) in terms(&r.energies) {
            if k != "increment" {
                dterm = dterm.max((v - summ["terms"][k].as_f64().unwrap_or(0.0)).abs());
            }
        }
        let dmol = molecule(&dir, Conventions::Axtb);
        let rd = Setup::new(&dmol, axtb_gxtb::v2::Model::v2_0_1(Conventions::Axtb))
            .unwrap()
            .scf(&ScfOptions::default())
            .unwrap();
        println!(
            "{name}: program mode dE {de:.2e} (rel {:.1e}), terms {dterm:.1e}, iter {} / {}; default conventions dE {:.2e}",
            de / ep,
            r.iterations,
            summ["scf_iterations"],
            rd.energies.total - ep
        );
        // (H2O)100: 7644 Eh summed over 300 atoms, round-off ~1e-11 Eh
        assert!((de / ep).abs() < 1e-14, "{name}: {de:e}");
        assert!(dterm < 5e-15 * ep.abs(), "{name}: terms {dterm:e}");
        assert_eq!(r.iterations as u64, summ["scf_iterations"].as_u64().unwrap());
    }
}
